#!/usr/bin/env bash
# Copy every source file that differs between C:\ob\net-up (the PS2Recomp worktree) and C:\ob\net-src (the runner's
# copy with generated files) for the hand-written trees, then list what was copied.
set -e
UP=/c/ob/net-up
SRC=/c/ob/net-src
for tree in ps2xIOP ps2xRuntime ps2xTest ps2xRecomp ps2xAnalyzer; do
    [ -d "$UP/$tree" ] || continue
    diff -rq "$UP/$tree" "$SRC/$tree" 2>/dev/null | sed -n 's/^Files \(.*\) and \(.*\) differ$/\1/p' | while read -r f; do
        # register_functions.cpp is generated by the recompile into net-src: never the worktree's placeholder.
        case "$f" in */src/runner/register_functions.cpp) echo "kept generated ${f#"$UP"/}"; continue ;; esac
        cp "$f" "$SRC/${f#"$UP"/}"; echo "updated ${f#"$UP"/}"
    done
    diff -rq "$UP/$tree" "$SRC/$tree" 2>/dev/null | sed -n "s|^Only in \($UP[^:]*\): \(.*\)$|\1/\2|p" | while read -r f; do
        if [ -f "$f" ]; then mkdir -p "$(dirname "$SRC/${f#"$UP"/}")"; cp "$f" "$SRC/${f#"$UP"/}"; echo "added ${f#"$UP"/}"; fi
    done
done
